class Solution {
    std::pair<int, int> dfs(int u, const std::vector<std::vector<int>>& adj, const std::vector<int>& value) {
        int totalSum = value[u];
        int totalCount = 1;
        for (int v : adj[u]) {
            auto [subSum, subCnt] = dfs(v, adj, value);
            totalSum += subSum;
            totalCount += subCnt;
        }
        if (totalSum == 0) return {0, 0};
        return {totalSum, totalCount};
    }
public:
    int deleteTreeNodes(int nodes, std::vector<int>& parent, std::vector<int>& value) {
        std::vector<std::vector<int>> adj(nodes);
        for (int i = 0; i < nodes; ++i) {
            if (parent[i] != -1) adj[parent[i]].push_back(i);
        }
        return dfs(0, adj, value).second;
    }
};

class Solution {
    int[] dfs(int u, java.util.List<java.util.List<Integer>> adj, int[] value) {
        int totalSum = value[u];
        int totalCount = 1;
        for (int v : adj.get(u)) {
            int[] sub = dfs(v, adj, value);
            totalSum += sub[0];
            totalCount += sub[1];
        }
        if (totalSum == 0) return new int[]{0, 0};
        return new int[]{totalSum, totalCount};
    }
    public int deleteTreeNodes(int nodes, int[] parent, int[] value) {
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
        for (int i = 0; i < nodes; i++) adj.add(new java.util.ArrayList<>());
        for (int i = 0; i < nodes; i++) {
            if (parent[i] != -1) adj.get(parent[i]).add(i);
        }
        return dfs(0, adj, value)[1];
    }
}

var deleteTreeNodes = function(nodes, parent, value) {
    const adj = Array.from({ length: nodes }, () => []);
    for (let i = 0; i < nodes; i++) {
